CREATE OR REPLACE FUNCTION aquasense.actualizar_conexion_red(p_conexion_id uuid, p_componente_origen_id uuid, p_componente_destino_id uuid, p_espacio_destino_id uuid, p_evento_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_antes aquasense.conexion%ROWTYPE;
    v_despues aquasense.conexion%ROWTYPE;
BEGIN
    IF p_conexion_id IS NULL
       OR p_componente_origen_id IS NULL
       OR p_evento_id IS NULL THEN
        RAISE EXCEPTION
            'Se requieren los identificadores de conexión, origen y evento.'
            USING ERRCODE = '23502';
    END IF;

    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION
            'La actualización de conexiones requiere READ COMMITTED.'
            USING ERRCODE = '25001';
    END IF;

    -- Coordinar el cambio con las demás operaciones de la red.
    PERFORM control_id
    FROM aquasense.control_red
    WHERE control_id = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No existe el registro de control de la red.'
            USING ERRCODE = '23514';
    END IF;

    SELECT *
    INTO v_antes
    FROM aquasense.conexion
    WHERE conexion_id = p_conexion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La conexión indicada no existe.'
            USING ERRCODE = '23503';
    END IF;

    IF v_antes.componente_origen_id IS NOT DISTINCT FROM p_componente_origen_id
       AND v_antes.componente_destino_id IS NOT DISTINCT FROM p_componente_destino_id
       AND v_antes.espacio_destino_id IS NOT DISTINCT FROM p_espacio_destino_id THEN
        RAISE EXCEPTION
            'La conexión no presenta cambios.'
            USING ERRCODE = '23514';
    END IF;

    -- El trigger existente valida tipos, estado, salidas y ciclos.
    UPDATE aquasense.conexion
    SET componente_origen_id = p_componente_origen_id,
        componente_destino_id = p_componente_destino_id,
        espacio_destino_id = p_espacio_destino_id
    WHERE conexion_id = p_conexion_id
    RETURNING * INTO v_despues;

    PERFORM aquasense.encolar_evento_red(
        p_evento_id,
        jsonb_build_object(
            'operacion', 'ACTUALIZAR_CONEXION',
            'antes', to_jsonb(v_antes),
            'despues', to_jsonb(v_despues)
        )
    );

    RETURN p_conexion_id;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.confirmar_evento_documental(p_evento_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_reporte_id UUID;
    v_estado_reporte TEXT;
    v_secuencia_reporte BIGINT;

    v_tipo_evento TEXT;
    v_estado_evento TEXT;
    v_secuencia_evento BIGINT;
BEGIN
    IF p_evento_id IS NULL THEN
        RAISE EXCEPTION
            'Se requiere el identificador del evento.'
            USING ERRCODE = '23502';
    END IF;

    -- Primero identificamos el reporte al que pertenece el evento.
    SELECT reporte_id
    INTO v_reporte_id
    FROM aquasense.evento_salida
    WHERE evento_id = p_evento_id
      AND destino = 'DOCUMENTAL';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El evento documental indicado no existe.'
            USING ERRCODE = '23503';
    END IF;

    -- Se bloquea primero el reporte, como en registrar_atencion.
    SELECT estado, secuencia_documental
    INTO v_estado_reporte, v_secuencia_reporte
    FROM aquasense.reporte
    WHERE reporte_id = v_reporte_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El reporte asociado al evento no existe.'
            USING ERRCODE = '23503';
    END IF;

    SELECT tipo, estado, secuencia
    INTO v_tipo_evento, v_estado_evento, v_secuencia_evento
    FROM aquasense.evento_salida
    WHERE evento_id = p_evento_id
      AND destino = 'DOCUMENTAL'
      AND reporte_id = v_reporte_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El evento documental indicado ya no está disponible.'
            USING ERRCODE = '23503';
    END IF;

    -- Permite repetir la confirmación sin aplicar cambios otra vez.
    IF v_estado_evento = 'PROCESADO' THEN
        RETURN;
    END IF;

    IF v_estado_evento <> 'PENDIENTE' THEN
        RAISE EXCEPTION
            'Solo se pueden confirmar eventos pendientes. Estado actual: %.',
            v_estado_evento
            USING ERRCODE = '23514';
    END IF;

    IF v_estado_reporte = 'CERRADO' THEN
        RAISE EXCEPTION
            'No se puede confirmar un evento pendiente de un reporte cerrado.'
            USING ERRCODE = '23514';
    END IF;

    IF v_secuencia_evento <> v_secuencia_reporte THEN
        RAISE EXCEPTION
            'La secuencia del evento no coincide con la secuencia actual del reporte.'
            USING ERRCODE = '23514';
    END IF;

    IF v_tipo_evento = 'CREAR_EXPEDIENTE' THEN
        IF v_secuencia_evento <> 1 THEN
            RAISE EXCEPTION
                'La creación del expediente debe tener la secuencia 1.'
                USING ERRCODE = '23514';
        END IF;

    ELSIF v_tipo_evento = 'AGREGAR_ATENCION' THEN
        IF v_secuencia_evento <= 1 OR NOT EXISTS (
            SELECT 1
            FROM aquasense.evento_salida
            WHERE destino = 'DOCUMENTAL'
              AND reporte_id = v_reporte_id
              AND secuencia = v_secuencia_evento - 1
              AND estado = 'PROCESADO'
        ) THEN
            RAISE EXCEPTION
                'La operación documental anterior no está confirmada.'
                USING ERRCODE = '23514';
        END IF;

    ELSE
        RAISE EXCEPTION
            'Tipo de evento documental no admitido: %.',
            v_tipo_evento
            USING ERRCODE = '23514';
    END IF;

    UPDATE aquasense.evento_salida
    SET estado = 'PROCESADO',
        procesado_en = CURRENT_TIMESTAMP,
        proximo_intento_en = NULL,
        ultimo_error = NULL
    WHERE evento_id = p_evento_id;

    IF v_tipo_evento = 'AGREGAR_ATENCION'
       AND v_estado_reporte = 'PENDIENTE' THEN

        UPDATE aquasense.reporte
        SET estado = 'EN_ATENCION',
            actualizado_en = CURRENT_TIMESTAMP
        WHERE reporte_id = v_reporte_id;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.confirmar_evento_grafo(p_evento_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_estado TEXT;
    v_secuencia BIGINT;
    v_version_red BIGINT;
BEGIN
    IF p_evento_id IS NULL THEN
        RAISE EXCEPTION
            'Se requiere el identificador del evento.'
            USING ERRCODE = '23502';
    END IF;

    -- Coordinar la comprobación con los cambios de versión de la red.
    SELECT version_red
    INTO v_version_red
    FROM aquasense.control_red
    WHERE control_id = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No existe el registro de control de la red.'
            USING ERRCODE = '23514';
    END IF;

    SELECT estado, secuencia
    INTO v_estado, v_secuencia
    FROM aquasense.evento_salida
    WHERE evento_id = p_evento_id
      AND destino = 'GRAFO'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El evento de grafo indicado no existe.'
            USING ERRCODE = '23503';
    END IF;

    -- Una confirmación repetida no vuelve a modificar el evento.
    IF v_estado = 'PROCESADO' THEN
        RETURN;
    END IF;

    IF v_estado <> 'PENDIENTE' THEN
        RAISE EXCEPTION
            'Solo se pueden confirmar eventos pendientes. Estado actual: %.',
            v_estado
            USING ERRCODE = '23514';
    END IF;

    IF v_secuencia > v_version_red THEN
        RAISE EXCEPTION
            'La secuencia del evento supera la versión actual de la red.'
            USING ERRCODE = '23514';
    END IF;

    IF v_secuencia > 1 AND NOT EXISTS (
        SELECT 1
        FROM aquasense.evento_salida
        WHERE destino = 'GRAFO'
          AND secuencia = v_secuencia - 1
          AND estado = 'PROCESADO'
    ) THEN
        RAISE EXCEPTION
            'El evento anterior del grafo no está confirmado.'
            USING ERRCODE = '23514';
    END IF;

    UPDATE aquasense.evento_salida
    SET estado = 'PROCESADO',
        procesado_en = CURRENT_TIMESTAMP,
        proximo_intento_en = NULL,
        ultimo_error = NULL
    WHERE evento_id = p_evento_id;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.crear_conexion_red(p_conexion_id uuid, p_componente_origen_id uuid, p_componente_destino_id uuid, p_espacio_destino_id uuid, p_evento_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_conexion aquasense.conexion%ROWTYPE;
BEGIN
    IF p_conexion_id IS NULL
       OR p_componente_origen_id IS NULL
       OR p_evento_id IS NULL THEN
        RAISE EXCEPTION
            'Se requieren los identificadores de conexión, origen y evento.'
            USING ERRCODE = '23502';
    END IF;

    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION
            'La creación de conexiones requiere READ COMMITTED.'
            USING ERRCODE = '25001';
    END IF;

    -- Coordinar el cambio con las demás operaciones de la red.
    PERFORM control_id
    FROM aquasense.control_red
    WHERE control_id = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No existe el registro de control de la red.'
            USING ERRCODE = '23514';
    END IF;

    -- Las restricciones y el trigger existentes validan la conexión.
    INSERT INTO aquasense.conexion (
        conexion_id,
        componente_origen_id,
        componente_destino_id,
        espacio_destino_id
    )
    VALUES (
        p_conexion_id,
        p_componente_origen_id,
        p_componente_destino_id,
        p_espacio_destino_id
    )
    RETURNING * INTO v_conexion;

    PERFORM aquasense.encolar_evento_red(
        p_evento_id,
        jsonb_build_object(
            'operacion', 'CREAR_CONEXION',
            'conexion', to_jsonb(v_conexion)
        )
    );

    RETURN p_conexion_id;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.eliminar_conexion_red(p_conexion_id uuid, p_evento_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_conexion aquasense.conexion%ROWTYPE;
BEGIN
    IF p_conexion_id IS NULL OR p_evento_id IS NULL THEN
        RAISE EXCEPTION
            'Se requieren los identificadores de conexión y evento.'
            USING ERRCODE = '23502';
    END IF;

    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION
            'La eliminación de conexiones requiere READ COMMITTED.'
            USING ERRCODE = '25001';
    END IF;

    -- Coordinar este cambio con las demás operaciones de la red.
    PERFORM control_id
    FROM aquasense.control_red
    WHERE control_id = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No existe el registro de control de la red.'
            USING ERRCODE = '23514';
    END IF;

    -- Conservar los datos de la conexión para el evento.
    DELETE FROM aquasense.conexion
    WHERE conexion_id = p_conexion_id
    RETURNING * INTO v_conexion;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La conexión indicada no existe.'
            USING ERRCODE = '23503';
    END IF;

    PERFORM aquasense.encolar_evento_red(
        p_evento_id,
        jsonb_build_object(
            'operacion', 'ELIMINAR_CONEXION',
            'conexion', to_jsonb(v_conexion)
        )
    );

    RETURN p_conexion_id;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.reemplazar_tuberia(p_reemplazo_id uuid, p_tuberia_anterior_id uuid, p_tuberia_nueva_id uuid, p_reporte_id uuid, p_evento_documental_id uuid, p_evento_grafo_id uuid, p_atencion jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_anterior aquasense.componente%ROWTYPE;
    v_nueva aquasense.componente%ROWTYPE;

    v_entrada_antes aquasense.conexion%ROWTYPE;
    v_entrada_despues aquasense.conexion%ROWTYPE;

    v_salida_antes aquasense.conexion%ROWTYPE;
    v_salida_despues aquasense.conexion%ROWTYPE;

    v_tiene_entrada BOOLEAN;
    v_tiene_salida BOOLEAN;
    v_estado_reporte TEXT;

    v_conexiones JSONB := '[]'::JSONB;
    v_atencion JSONB;
BEGIN
    IF p_reemplazo_id IS NULL
       OR p_tuberia_anterior_id IS NULL
       OR p_tuberia_nueva_id IS NULL
       OR p_reporte_id IS NULL
       OR p_evento_documental_id IS NULL
       OR p_evento_grafo_id IS NULL THEN
        RAISE EXCEPTION
            'Se requieren todos los identificadores del reemplazo.'
            USING ERRCODE = '23502';
    END IF;

    IF p_tuberia_anterior_id = p_tuberia_nueva_id THEN
        RAISE EXCEPTION
            'La tubería anterior y la nueva deben ser diferentes.'
            USING ERRCODE = '23514';
    END IF;

    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION
            'El reemplazo requiere el aislamiento READ COMMITTED.'
            USING ERRCODE = '25001';
    END IF;

    IF p_atencion IS NULL
       OR jsonb_typeof(p_atencion) IS DISTINCT FROM 'object'
       OR (p_atencion ->> 'tipo') IS DISTINCT FROM 'REPARACION' THEN
        RAISE EXCEPTION
            'El reemplazo requiere una atención de tipo REPARACION.'
            USING ERRCODE = '23514';
    END IF;

    -- Coordinar los cambios de topología.
    PERFORM control_id
    FROM aquasense.control_red
    WHERE control_id = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No existe el registro de control de la red.'
            USING ERRCODE = '23514';
    END IF;

    -- Bloquear el reporte antes de registrar la atención.
    SELECT estado
    INTO v_estado_reporte
    FROM aquasense.reporte
    WHERE reporte_id = p_reporte_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El reporte indicado no existe.'
            USING ERRCODE = '23503';
    END IF;

    IF v_estado_reporte = 'CERRADO' THEN
        RAISE EXCEPTION
            'No se puede asociar un reemplazo a un reporte cerrado.'
            USING ERRCODE = '23514';
    END IF;

    -- Bloquear ambos componentes en un orden estable.
    PERFORM componente_id
    FROM aquasense.componente
    WHERE componente_id IN (
        p_tuberia_anterior_id,
        p_tuberia_nueva_id
    )
    ORDER BY componente_id
    FOR UPDATE;

    SELECT *
    INTO v_anterior
    FROM aquasense.componente
    WHERE componente_id = p_tuberia_anterior_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tubería anterior no existe.'
            USING ERRCODE = '23503';
    END IF;

    SELECT *
    INTO v_nueva
    FROM aquasense.componente
    WHERE componente_id = p_tuberia_nueva_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La tubería nueva no existe.'
            USING ERRCODE = '23503';
    END IF;

    IF v_anterior.tipo <> 'TUBERIA'
       OR v_nueva.tipo <> 'TUBERIA' THEN
        RAISE EXCEPTION
            'Ambos componentes deben ser tuberías.'
            USING ERRCODE = '23514';
    END IF;

    IF v_anterior.estado <> 'ACTIVO'
       OR v_nueva.estado <> 'ACTIVO' THEN
        RAISE EXCEPTION
            'Ambas tuberías deben estar activas antes del reemplazo.'
            USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM aquasense.conexion
        WHERE componente_origen_id = p_tuberia_nueva_id
           OR componente_destino_id = p_tuberia_nueva_id
    ) THEN
        RAISE EXCEPTION
            'La tubería nueva no debe tener conexiones actuales.'
            USING ERRCODE = '23514';
    END IF;

    -- Una tubería solo puede ser reemplazada una vez y una nueva
    -- solo puede reemplazar directamente a una tubería anterior.
    IF EXISTS (
        SELECT 1
        FROM aquasense.reemplazo_tuberia
        WHERE tuberia_anterior_id = p_tuberia_anterior_id
           OR tuberia_nueva_id = p_tuberia_nueva_id
    ) THEN
        RAISE EXCEPTION
            'La relación de reemplazo entra en conflicto con un reemplazo existente.'
            USING ERRCODE = '23514';
    END IF;

    -- Evitar ciclos en la cadena de reemplazos.
    IF EXISTS (
        WITH RECURSIVE cadena AS (
            SELECT p_tuberia_nueva_id AS tuberia_id

            UNION

            SELECT r.tuberia_nueva_id
            FROM aquasense.reemplazo_tuberia AS r
            JOIN cadena AS c
                ON r.tuberia_anterior_id = c.tuberia_id
        )
        SELECT 1
        FROM cadena
        WHERE tuberia_id = p_tuberia_anterior_id
    ) THEN
        RAISE EXCEPTION
            'El reemplazo formaría un ciclo en el historial.'
            USING ERRCODE = '23514';
    END IF;

    -- Obtener las conexiones actuales de la tubería anterior.
    SELECT *
    INTO v_entrada_antes
    FROM aquasense.conexion
    WHERE componente_destino_id = p_tuberia_anterior_id;

    v_tiene_entrada := FOUND;

    SELECT *
    INTO v_salida_antes
    FROM aquasense.conexion
    WHERE componente_origen_id = p_tuberia_anterior_id;

    v_tiene_salida := FOUND;

    IF NOT v_tiene_entrada AND NOT v_tiene_salida THEN
        RAISE EXCEPTION
            'La tubería anterior no tiene conexiones actuales.'
            USING ERRCODE = '23514';
    END IF;

    IF v_tiene_entrada THEN
        UPDATE aquasense.conexion
        SET componente_destino_id = p_tuberia_nueva_id
        WHERE conexion_id = v_entrada_antes.conexion_id
        RETURNING * INTO v_entrada_despues;

        v_conexiones := v_conexiones || jsonb_build_array(
            jsonb_build_object(
                'antes', to_jsonb(v_entrada_antes),
                'despues', to_jsonb(v_entrada_despues)
            )
        );
    END IF;

    IF v_tiene_salida THEN
        UPDATE aquasense.conexion
        SET componente_origen_id = p_tuberia_nueva_id
        WHERE conexion_id = v_salida_antes.conexion_id
        RETURNING * INTO v_salida_despues;

        v_conexiones := v_conexiones || jsonb_build_array(
            jsonb_build_object(
                'antes', to_jsonb(v_salida_antes),
                'despues', to_jsonb(v_salida_despues)
            )
        );
    END IF;

    -- Ya sin conexiones, la tubería anterior puede retirarse.
    UPDATE aquasense.componente
    SET estado = 'RETIRADO'
    WHERE componente_id = p_tuberia_anterior_id
    RETURNING * INTO v_anterior;

    INSERT INTO aquasense.reemplazo_tuberia (
        reemplazo_id,
        tuberia_anterior_id,
        tuberia_nueva_id,
        reporte_id
    )
    VALUES (
        p_reemplazo_id,
        p_tuberia_anterior_id,
        p_tuberia_nueva_id,
        p_reporte_id
    );

    -- Asociar ambas tuberías al reporte.
    INSERT INTO aquasense.reporte_componente (
        reporte_id,
        componente_id
    )
    VALUES
        (p_reporte_id, p_tuberia_anterior_id),
        (p_reporte_id, p_tuberia_nueva_id)
    ON CONFLICT (reporte_id, componente_id) DO NOTHING;

    -- La atención apunta a la tubería instalada. La relación
    -- formal con la anterior queda en reemplazo_tuberia.
    v_atencion := jsonb_set(
        p_atencion,
        '{componenteId}',
        to_jsonb(p_tuberia_nueva_id::TEXT),
        TRUE
    );

    PERFORM aquasense.registrar_atencion(
        p_evento_documental_id,
        p_reporte_id,
        v_atencion
    );

    -- Encolar el cambio incremental para Neo4j.
    PERFORM aquasense.encolar_evento_red(
        p_evento_grafo_id,
        jsonb_build_object(
            'operacion', 'REEMPLAZAR_TUBERIA',
            'reemplazoId', p_reemplazo_id::TEXT,
            'reporteId', p_reporte_id::TEXT,
            'tuberiaAnterior', to_jsonb(v_anterior),
            'tuberiaNueva', to_jsonb(v_nueva),
            'conexiones', v_conexiones
        )
    );

    RETURN p_reemplazo_id;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.registrar_atencion(p_evento_id uuid, p_reporte_id uuid, p_atencion jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_estado_reporte TEXT;
    v_secuencia_actual BIGINT;
    v_nueva_secuencia BIGINT;

    v_atencion_id UUID;
    v_componente_id UUID;
    v_tipo TEXT;
    v_fecha TIMESTAMPTZ;
BEGIN
    -- Validaciones generales.
    IF p_evento_id IS NULL OR p_reporte_id IS NULL THEN
        RAISE EXCEPTION
            'Se requieren los identificadores del evento y del reporte.'
            USING ERRCODE = '23502';
    END IF;

    IF p_atencion IS NULL
       OR jsonb_typeof(p_atencion) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION
            'La atención debe ser un objeto JSON.'
            USING ERRCODE = '23514';
    END IF;

    IF jsonb_typeof(p_atencion -> 'atencionId') IS DISTINCT FROM 'string'
       OR btrim(p_atencion ->> 'atencionId') = '' THEN
        RAISE EXCEPTION
            'La atención requiere un identificador.'
            USING ERRCODE = '23514';
    END IF;

    BEGIN
        v_atencion_id := (p_atencion ->> 'atencionId')::UUID;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'El identificador de la atención debe ser un UUID válido.'
                USING ERRCODE = '23514';
    END;

    IF jsonb_typeof(p_atencion -> 'tipo') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION
            'La atención requiere un tipo.'
            USING ERRCODE = '23514';
    END IF;

    v_tipo := p_atencion ->> 'tipo';

    IF v_tipo NOT IN ('INSPECCION', 'REPARACION', 'VERIFICACION') THEN
        RAISE EXCEPTION
            'Tipo de atención inválido: %.', v_tipo
            USING ERRCODE = '23514';
    END IF;

    IF jsonb_typeof(p_atencion -> 'fecha') IS DISTINCT FROM 'string'
       OR (p_atencion ->> 'fecha') !~
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
        RAISE EXCEPTION
            'La fecha debe incluir fecha, hora y zona horaria.'
            USING ERRCODE = '23514';
    END IF;

    BEGIN
        v_fecha := (p_atencion ->> 'fecha')::TIMESTAMPTZ;
    EXCEPTION
        WHEN invalid_datetime_format OR datetime_field_overflow THEN
            RAISE EXCEPTION
                'La fecha de la atención no es válida.'
                USING ERRCODE = '23514';
    END;

    IF NOT isfinite(v_fecha) THEN
        RAISE EXCEPTION
            'La fecha de la atención debe ser finita.'
            USING ERRCODE = '23514';
    END IF;

    IF jsonb_typeof(p_atencion -> 'descripcion') IS DISTINCT FROM 'string'
       OR btrim(p_atencion ->> 'descripcion') = '' THEN
        RAISE EXCEPTION
            'La atención requiere una descripción.'
            USING ERRCODE = '23514';
    END IF;

    -- El componente es opcional. Si se proporciona, debe existir.
    IF p_atencion ? 'componenteId'
       AND p_atencion -> 'componenteId' <> 'null'::JSONB THEN

        IF jsonb_typeof(p_atencion -> 'componenteId') IS DISTINCT FROM 'string'
           OR btrim(p_atencion ->> 'componenteId') = '' THEN
            RAISE EXCEPTION
                'El componente debe identificarse con un UUID válido.'
                USING ERRCODE = '23514';
        END IF;

        BEGIN
            v_componente_id := (p_atencion ->> 'componenteId')::UUID;
        EXCEPTION
            WHEN invalid_text_representation THEN
                RAISE EXCEPTION
                    'El componente debe identificarse con un UUID válido.'
                    USING ERRCODE = '23514';
        END;

        IF NOT EXISTS (
            SELECT 1
            FROM aquasense.componente
            WHERE componente_id = v_componente_id
        ) THEN
            RAISE EXCEPTION
                'El componente indicado no existe.'
                USING ERRCODE = '23503';
        END IF;
    END IF;

    -- Campos específicos de cada tipo.
    IF v_tipo = 'INSPECCION' THEN
        IF jsonb_typeof(p_atencion -> 'hallazgos') IS DISTINCT FROM 'string'
           OR btrim(p_atencion ->> 'hallazgos') = '' THEN
            RAISE EXCEPTION
                'La inspección requiere registrar sus hallazgos.'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF v_tipo = 'REPARACION' AND p_atencion ? 'materiales' THEN
        IF jsonb_typeof(p_atencion -> 'materiales') IS DISTINCT FROM 'array' THEN
            RAISE EXCEPTION
                'Los materiales deben ser una lista.'
                USING ERRCODE = '23514';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM jsonb_array_elements(p_atencion -> 'materiales') AS material(valor)
            WHERE jsonb_typeof(material.valor) <> 'string'
               OR btrim(material.valor #>> '{}') = ''
        ) THEN
            RAISE EXCEPTION
                'Cada material debe ser un texto no vacío.'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF v_tipo = 'VERIFICACION' THEN
        IF jsonb_typeof(p_atencion -> 'resultado') IS DISTINCT FROM 'string'
           OR (p_atencion ->> 'resultado') NOT IN (
               'SIN_INDICIOS',
               'PERSISTE',
               'NO_CONCLUYENTE'
           ) THEN
            RAISE EXCEPTION
                'La verificación requiere un resultado válido.'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    -- Bloquear el reporte para ordenar las operaciones sobre él.
    SELECT estado, secuencia_documental
    INTO v_estado_reporte, v_secuencia_actual
    FROM aquasense.reporte
    WHERE reporte_id = p_reporte_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El reporte indicado no existe.'
            USING ERRCODE = '23503';
    END IF;

    IF v_estado_reporte = 'CERRADO' THEN
        RAISE EXCEPTION
            'No se pueden agregar atenciones a un reporte cerrado.'
            USING ERRCODE = '23514';
    END IF;

    -- El expediente y cualquier atención anterior deben estar confirmados.
    IF v_secuencia_actual < 1 OR NOT EXISTS (
        SELECT 1
        FROM aquasense.evento_salida
        WHERE destino = 'DOCUMENTAL'
          AND reporte_id = p_reporte_id
          AND secuencia = v_secuencia_actual
          AND estado = 'PROCESADO'
    ) THEN
        RAISE EXCEPTION
            'El reporte tiene una operación documental pendiente o sin confirmar.'
            USING ERRCODE = '23514';
    END IF;

    -- No reutilizar el identificador de una atención en este reporte.
    IF EXISTS (
        SELECT 1
        FROM aquasense.evento_salida
        WHERE destino = 'DOCUMENTAL'
          AND reporte_id = p_reporte_id
          AND tipo = 'AGREGAR_ATENCION'
          AND datos -> 'atencion' ->> 'atencionId' = v_atencion_id::TEXT
    ) THEN
        RAISE EXCEPTION
            'La atención ya fue registrada para este reporte.'
            USING ERRCODE = '23505';
    END IF;

    v_nueva_secuencia := v_secuencia_actual + 1;

    UPDATE aquasense.reporte
    SET secuencia_documental = v_nueva_secuencia,
        actualizado_en = CURRENT_TIMESTAMP
    WHERE reporte_id = p_reporte_id;

    INSERT INTO aquasense.evento_salida (
        evento_id,
        destino,
        tipo,
        reporte_id,
        secuencia,
        datos
    )
    VALUES (
        p_evento_id,
        'DOCUMENTAL',
        'AGREGAR_ATENCION',
        p_reporte_id,
        v_nueva_secuencia,
        jsonb_build_object(
            'reporteId', p_reporte_id::TEXT,
            'atencion',
            jsonb_set(
                p_atencion,
                '{atencionId}',
                to_jsonb(v_atencion_id::TEXT)
            )
        )
    );

    RETURN p_evento_id;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.registrar_fallo_documental(p_evento_id uuid, p_error text, p_proximo_intento_en timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_reporte_id UUID;
    v_estado_evento TEXT;
    v_intentos_actuales INTEGER;
    v_nuevos_intentos INTEGER;
    v_nuevo_estado TEXT;
BEGIN
    IF p_evento_id IS NULL THEN
        RAISE EXCEPTION
            'Se requiere el identificador del evento.'
            USING ERRCODE = '23502';
    END IF;

    IF p_error IS NULL OR btrim(p_error) = '' THEN
        RAISE EXCEPTION
            'Se requiere una descripción del error.'
            USING ERRCODE = '23514';
    END IF;

    SELECT reporte_id
    INTO v_reporte_id
    FROM aquasense.evento_salida
    WHERE evento_id = p_evento_id
      AND destino = 'DOCUMENTAL';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El evento documental indicado no existe.'
            USING ERRCODE = '23503';
    END IF;

    -- Mantener el mismo orden de bloqueo que las demás funciones.
    PERFORM 1
    FROM aquasense.reporte
    WHERE reporte_id = v_reporte_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El reporte asociado al evento no existe.'
            USING ERRCODE = '23503';
    END IF;

    SELECT estado, intentos
    INTO v_estado_evento, v_intentos_actuales
    FROM aquasense.evento_salida
    WHERE evento_id = p_evento_id
      AND destino = 'DOCUMENTAL'
      AND reporte_id = v_reporte_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El evento documental indicado ya no está disponible.'
            USING ERRCODE = '23503';
    END IF;

    IF v_estado_evento <> 'PENDIENTE' THEN
        RAISE EXCEPTION
            'Solo se pueden registrar fallos de eventos pendientes. Estado actual: %.',
            v_estado_evento
            USING ERRCODE = '23514';
    END IF;

    v_nuevos_intentos := v_intentos_actuales + 1;

    IF v_nuevos_intentos < 3 THEN
        IF p_proximo_intento_en IS NULL
           OR NOT isfinite(p_proximo_intento_en)
           OR p_proximo_intento_en <= CURRENT_TIMESTAMP THEN
            RAISE EXCEPTION
                'Se requiere una fecha futura para el próximo intento.'
                USING ERRCODE = '23514';
        END IF;

        v_nuevo_estado := 'PENDIENTE';
    ELSE
        v_nuevo_estado := 'ERROR';
    END IF;

    UPDATE aquasense.evento_salida
    SET intentos = v_nuevos_intentos,
        estado = v_nuevo_estado,
        ultimo_error = btrim(p_error),
        proximo_intento_en = CASE
            WHEN v_nuevo_estado = 'PENDIENTE'
                THEN p_proximo_intento_en
            ELSE NULL
        END
    WHERE evento_id = p_evento_id;

    RETURN v_nuevo_estado;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.registrar_fallo_grafo(p_evento_id uuid, p_error text, p_proximo_intento_en timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_estado TEXT;
    v_secuencia BIGINT;
    v_intentos INTEGER;
    v_nuevos_intentos INTEGER;
    v_nuevo_estado TEXT;
BEGIN
    IF p_evento_id IS NULL THEN
        RAISE EXCEPTION
            'Se requiere el identificador del evento.'
            USING ERRCODE = '23502';
    END IF;

    IF p_error IS NULL OR btrim(p_error) = '' THEN
        RAISE EXCEPTION
            'Se requiere una descripción del error.'
            USING ERRCODE = '23514';
    END IF;

    -- Mantener el orden de bloqueo usado para confirmar eventos.
    PERFORM control_id
    FROM aquasense.control_red
    WHERE control_id = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No existe el registro de control de la red.'
            USING ERRCODE = '23514';
    END IF;

    SELECT estado, secuencia, intentos
    INTO v_estado, v_secuencia, v_intentos
    FROM aquasense.evento_salida
    WHERE evento_id = p_evento_id
      AND destino = 'GRAFO'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El evento de grafo indicado no existe.'
            USING ERRCODE = '23503';
    END IF;

    IF v_estado <> 'PENDIENTE' THEN
        RAISE EXCEPTION
            'Solo se pueden registrar fallos de eventos pendientes. Estado actual: %.',
            v_estado
            USING ERRCODE = '23514';
    END IF;

    -- No se procesa un evento si el anterior sigue sin confirmar.
    IF v_secuencia > 1 AND NOT EXISTS (
        SELECT 1
        FROM aquasense.evento_salida
        WHERE destino = 'GRAFO'
          AND secuencia = v_secuencia - 1
          AND estado = 'PROCESADO'
    ) THEN
        RAISE EXCEPTION
            'El evento anterior del grafo no está confirmado.'
            USING ERRCODE = '23514';
    END IF;

    v_nuevos_intentos := v_intentos + 1;

    IF v_nuevos_intentos < 3 THEN
        IF p_proximo_intento_en IS NULL
           OR NOT isfinite(p_proximo_intento_en)
           OR p_proximo_intento_en <= CURRENT_TIMESTAMP THEN
            RAISE EXCEPTION
                'Se requiere una fecha futura para el próximo intento.'
                USING ERRCODE = '23514';
        END IF;

        v_nuevo_estado := 'PENDIENTE';
    ELSE
        v_nuevo_estado := 'ERROR';
    END IF;

    UPDATE aquasense.evento_salida
    SET intentos = v_nuevos_intentos,
        estado = v_nuevo_estado,
        ultimo_error = btrim(p_error),
        proximo_intento_en = CASE
            WHEN v_nuevo_estado = 'PENDIENTE'
                THEN p_proximo_intento_en
            ELSE NULL
        END
    WHERE evento_id = p_evento_id;

    RETURN v_nuevo_estado;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.validar_conexion_red()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_tipo_origen aquasense.componente.tipo%TYPE;
    v_estado_origen aquasense.componente.estado%TYPE;

    v_tipo_destino aquasense.componente.tipo%TYPE;
    v_estado_destino aquasense.componente.estado%TYPE;

    v_conexion_anterior UUID;
    v_forma_ciclo BOOLEAN;
BEGIN
    -- Coordinamos las modificaciones de conexiones mediante
    -- la fila de control de la red.
    PERFORM control_id
    FROM aquasense.control_red
    WHERE control_id = 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No existe el registro de control de la red.'
            USING ERRCODE = '23514';
    END IF;

    -- Al actualizar, excluimos la fila anterior de las
    -- comprobaciones de salidas y recorridos.
    IF TG_OP = 'UPDATE' THEN
        v_conexion_anterior := OLD.conexion_id;
    END IF;


    -- La conexión debe tener exactamente un destino.
    IF (
        NEW.componente_destino_id IS NULL
        AND NEW.espacio_destino_id IS NULL
    ) OR (
        NEW.componente_destino_id IS NOT NULL
        AND NEW.espacio_destino_id IS NOT NULL
    ) THEN
        RAISE EXCEPTION
            'La conexión debe tener un solo destino: componente o espacio.'
            USING ERRCODE = '23514';
    END IF;


    -- Consultar el componente de origen.
    SELECT tipo, estado
    INTO v_tipo_origen, v_estado_origen
    FROM aquasense.componente
    WHERE componente_id = NEW.componente_origen_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El componente de origen no existe.'
            USING ERRCODE = '23503';
    END IF;

    IF v_estado_origen <> 'ACTIVO' THEN
        RAISE EXCEPTION
            'El componente de origen debe estar activo.'
            USING ERRCODE = '23514';
    END IF;


    -- Solo las uniones pueden tener más de una salida.
    IF v_tipo_origen <> 'UNION'
       AND EXISTS (
           SELECT 1
           FROM aquasense.conexion AS c
           WHERE c.componente_origen_id = NEW.componente_origen_id
             AND (
                 v_conexion_anterior IS NULL
                 OR c.conexion_id <> v_conexion_anterior
             )
       )
    THEN
        RAISE EXCEPTION
            'El componente de origen ya tiene una salida registrada.'
            USING ERRCODE = '23514';
    END IF;


    -- Si el destino es un espacio, el origen debe ser tubería.
    IF NEW.espacio_destino_id IS NOT NULL THEN
        IF v_tipo_origen <> 'TUBERIA' THEN
            RAISE EXCEPTION
                'Solo una tubería puede conectarse directamente a un espacio.'
                USING ERRCODE = '23514';
        END IF;

        -- La clave foránea comprueba que el espacio exista.
        RETURN NEW;
    END IF;


    -- A partir de aquí, el destino es otro componente.
    IF NEW.componente_origen_id = NEW.componente_destino_id THEN
        RAISE EXCEPTION
            'Un componente no puede conectarse consigo mismo.'
            USING ERRCODE = '23514';
    END IF;

    SELECT tipo, estado
    INTO v_tipo_destino, v_estado_destino
    FROM aquasense.componente
    WHERE componente_id = NEW.componente_destino_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El componente de destino no existe.'
            USING ERRCODE = '23503';
    END IF;

    IF v_estado_destino <> 'ACTIVO' THEN
        RAISE EXCEPTION
            'El componente de destino debe estar activo.'
            USING ERRCODE = '23514';
    END IF;


    -- Validar las combinaciones de tipos permitidas.
    IF NOT (
        (
            v_tipo_origen = 'CISTERNA'
            AND v_tipo_destino = 'TUBERIA'
        )
        OR (
            v_tipo_origen = 'TUBERIA'
            AND v_tipo_destino IN (
                'TUBERIA',
                'UNION',
                'VALVULA',
                'MEDIDOR'
            )
        )
        OR (
            v_tipo_origen = 'UNION'
            AND v_tipo_destino = 'TUBERIA'
        )
        OR (
            v_tipo_origen = 'VALVULA'
            AND v_tipo_destino = 'TUBERIA'
        )
        OR (
            v_tipo_origen = 'MEDIDOR'
            AND v_tipo_destino = 'TUBERIA'
        )
    ) THEN
        RAISE EXCEPTION
            'Conexión no permitida: % hacia %.',
            v_tipo_origen,
            v_tipo_destino
            USING ERRCODE = '23514';
    END IF;


    -- Si desde el destino ya se puede llegar al origen,
    -- agregar la nueva conexión cerraría un ciclo.
    WITH RECURSIVE recorrido AS (
        SELECT NEW.componente_destino_id AS componente_id

        UNION

        SELECT c.componente_destino_id
        FROM aquasense.conexion AS c
        INNER JOIN recorrido AS r
            ON c.componente_origen_id = r.componente_id
        WHERE c.componente_destino_id IS NOT NULL
          AND (
              v_conexion_anterior IS NULL
              OR c.conexion_id <> v_conexion_anterior
          )
    )
    SELECT EXISTS (
        SELECT 1
        FROM recorrido
        WHERE componente_id = NEW.componente_origen_id
    )
    INTO v_forma_ciclo;

    IF v_forma_ciclo THEN
        RAISE EXCEPTION
            'La conexión formaría un ciclo en la red.'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION aquasense.validar_subtipo_componente()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- En una eliminación o actualización se revisa el componente
    -- al que pertenecía la fila anterior.
    IF TG_OP IN ('DELETE', 'UPDATE') THEN
        PERFORM aquasense.comprobar_subtipo_componente(
            OLD.componente_id
        );
    END IF;

    -- En una inserción o actualización se revisa el componente
    -- al que pertenece la fila nueva.
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        PERFORM aquasense.comprobar_subtipo_componente(
            NEW.componente_id
        );
    END IF;

    RETURN NULL;
END;
$function$
